function makeThumbnails(){thumbnailObserver.disconnect();const list=$('thumbnails');list.replaceChildren();for(let i=1;i<=doc.numPages;i++){const b=document.createElement('button');b.className='thumbnail';b.dataset.page=i;const label=document.createElement('span');label.textContent='第 '+i+' 页';b.append(label);b.onclick=e=>{const selected=activeTab.selectedPages||new Set([current]);if(e.shiftKey){const anchor=activeTab.selectionAnchor||current;selected.clear();for(let n=Math.min(anchor,i);n<=Math.max(anchor,i);n++)selected.add(n)}else if(e.ctrlKey||e.metaKey){if(selected.has(i)&&selected.size>1)selected.delete(i);else selected.add(i);activeTab.selectionAnchor=i}else{selected.clear();selected.add(i);activeTab.selectionAnchor=i}activeTab.selectedPages=selected;go(i);updatePageControls();updateEditControls()};list.append(b);thumbnailObserver.observe(b)}}
