 try {const loading=pdfjs.getDocument({url:data.url,disableRange:true,disableStream:true,cMapUrl:'./vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'./vendor/standard_fonts/',wasmUrl:new URL('./vendor/wasm/',import.meta.url).href,isEvalSupported:false});const next=await loading.promise;let risk='';try{const info=(await next.getMetadata()).info||{};risk=info.IsSignaturesPresent?'检测到数字签名，已限制编辑':(info.IsAcroFormPresent||info.IsXFAPresent)?'检测到表单，已限制编辑':info.IsCollectionPresent?'检测到 PDF 文件包，已限制编辑':''}catch{risk='无法检查文档结构，已限制编辑'}const tab={risk,dirty:false,bytes:null,history:[],doc:next,name:data.name,token:data.token,current:1,scale:1,fitMode:'width',viewRotation:0,searchNeedle:'',searchHits:[],hitIndex:0,query:'',scrollTop:0};documents.push(tab);activateTab(tab);send('recent-record',{token:data.token});status(risk||('已打开 · '+next.numPages+' 页'));}
