async function search(){if(!doc)return;const q=$('query').value.trim().toLocaleLowerCase();if(!q)return;const source=doc,id=++searchId,hits=[];status('正在查找…');for(let n=1;n<=source.numPages;n++){const p=await source.getPage(n);const t=await p.getTextContent();if(id!==searchId||source!==doc)return;if(t.items.map(x=>x.str||'').join(' ').toLocaleLowerCase().includes(q))hits.push(n);}searchNeedle=q;searchHits=hits;hitIndex=0;$('search-next').disabled=!hits.length;$('matches').textContent=hits.length?'1 / '+hits.length+' 页':'未找到';if(hits.length)go(hits[0]);else if(CSS.highlights)CSS.highlights.delete('lite-search');status('查找完成：'+hits.length+' 页包含结果');}
