$('present-prev').onclick=()=>advancePresentation(-1);$('present-next').onclick=()=>advancePresentation(1);$('presentation-page').onclick=()=>advancePresentation(1);$('present-exit').onclick=()=>{if(document.fullscreenElement===$('presentation'))document.exitFullscreen()};
