document.addEventListener('keydown',e=>{if(document.fullscreenElement!==$('presentation'))return;if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();advancePresentation(1)}else if(['ArrowLeft','ArrowUp','PageUp','Backspace'].includes(e.key)){e.preventDefault();advancePresentation(-1)}else if(e.key==='Home'){e.preventDefault();current=1;renderPresentation()}else if(e.key==='End'){e.preventDefault();current=doc.numPages;renderPresentation()}else if(e.key==='Escape'){e.preventDefault();document.exitFullscreen()}});
