function updateEditControls(){const can=!!activeTab&&!activeTab.risk&&!operationBusy&&!pendingSave;for(const id of ['edit-rotate','edit-remove','edit-up','edit-down','edit-undo','extract','insert','merge','split','compress-scan','lite-highlight','lite-highlight-remove','lite-note','lite-text','lite-signature'])$(id).disabled=!can;if(can){$('edit-remove').disabled=(activeTab.selectedPages?.size||1)>=doc.numPages;$('edit-up').disabled=current<=1;$('edit-down').disabled=current>=doc.numPages;$('edit-undo').disabled=!activeTab.history.length;$('insert').disabled=$('merge').disabled=false}$('save').disabled=!activeTab||operationBusy||!!pendingSave;$('save-direct').disabled=!activeTab||!activeTab.dirty||operationBusy||!!pendingSave;$('present').disabled=!activeTab||operationBusy||!!pendingSave;$('page-png').disabled=!activeTab||operationBusy||!!pendingSave;$('images-pdf').disabled=operationBusy||!!pendingSave;}
