$('assemble-files').onchange=async e=>{const files=[...e.target.files],session=assembly;if(!session||!files.length)return;if(session.loading)return;session.loading=true;operationBusy=true;updateEditControls();try{if(files.length>20||files.reduce((n,f)=>n+f.size,0)>200*1024*1024)throw Error('一次最多选择 20 个文件，合计不超过 200 MiB');if(!session.sources.length){const original=new Uint8Array(session.tab.bytes||await session.tab.doc.getData()),pdf=await PDFLib.PDFDocument.load(original,{updateMetadata:false});if(pdf.getForm().getFields().length)throw Error('当前文档包含表单，无法整理');session.sources.push({name:session.tab.name,preview:session.tab.doc,pdf,owned:false});session.pages=pdf.getPageIndices().map(index=>({source:0,index,key:crypto.randomUUID()}))}const additions=[];for(const file of files){$('assemble-status').textContent='正在读取 '+file.name;const bytes=new Uint8Array(await file.arrayBuffer()),preview=await pdfjs.getDocument({data:new Uint8Array(bytes),cMapUrl:'./vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'./vendor/standard_fonts/',wasmUrl:new URL('./vendor/wasm/',import.meta.url).href,isEvalSupported:false}).promise;try{const info=(await preview.getMetadata()).info||{};if(info.IsSignaturesPresent||info.IsAcroFormPresent||info.IsXFAPresent||info.IsCollectionPresent)throw Error('含签名、表单或文件包，无法整理');const pdf=await PDFLib.PDFDocument.load(bytes,{updateMetadata:false});if(pdf.getForm().getFields().length)throw Error('包含表单，无法整理');if(session.pages.length+additions.length+pdf.getPageCount()>200)throw Error('预览最多支持 200 页');const source=session.sources.length;session.sources.push({name:file.name,preview,pdf,owned:true});additions.push(...pdf.getPageIndices().map(index=>({source,index,key:crypto.randomUUID()})))}catch(err){preview.loadingTask.destroy().catch(()=>{});throw Error(file.name+'：'+err.message)}}const insertAt=session.kind==='insert'&&!$('assemble-dialog').open?Math.min(session.page,session.pages.length):session.pages.length;session.pages.splice(insertAt,0,...additions);$('assemble-title').textContent=session.kind==='insert'?'预览并插入页面':'预览并合并页面';if(!$('assemble-dialog').open)$('assemble-dialog').showModal();renderAssembly();status('已加载文件，请检查页面顺序')}catch(err){status('无法读取文件：'+err.message);$('assemble-status').textContent=err.message;if(!$('assemble-dialog').open){for(const src of session.sources)if(src.owned)src.preview.loadingTask.destroy().catch(()=>{});assembly=null}}finally{session.loading=false;operationBusy=false;updateEditControls()}};
function renderAssembly(){const session=assembly;if(!session)return;const grid=$('assemble-grid');grid.replaceChildren();$('assemble-count').textContent='共 '+session.pages.length+' 页';$('assemble-status').textContent='拖动页面调整顺序';$('assemble-apply').disabled=!session.pages.length;for(const [position,item] of session.pages.entries()){const card=document.createElement('div');card.className='assemble-card';card.draggable=true;card.dataset.key=item.key;card.setAttribute('aria-label',session.sources[item.source].name+' 第 '+(item.index+1)+' 页');const canvas=document.createElement('canvas');const name=document.createElement('div');name.className='assemble-name';name.textContent=session.sources[item.source].name;name.title=name.textContent;const number=document.createElement('small');number.textContent='第 '+(item.index+1)+' 页';const actions=document.createElement('div');actions.className='assemble-actions';for(const [label,delta] of [['←',-1],['→',1],['×',0]]){const button=document.createElement('button');button.textContent=label;button.title=delta<0?'Move left':delta>0?'Move right':'Remove';button.setAttribute('aria-label',(delta<0?'前移':delta>0?'后移':'移除')+' '+name.textContent+' 第 '+(item.index+1)+' 页');button.disabled=delta<0?position===0:delta>0?position===session.pages.length-1:session.pages.length===1;button.onclick=()=>{if(delta===0)session.pages.splice(position,1);else{session.pages.splice(position,1);session.pages.splice(position+delta,0,item)}renderAssembly()};actions.append(button)}card.ondragstart=e=>{e.dataTransfer.setData('text/plain',item.key);e.dataTransfer.effectAllowed='move'};card.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move'};card.ondrop=e=>{e.preventDefault();const from=session.pages.findIndex(x=>x.key===e.dataTransfer.getData('text/plain')),to=session.pages.indexOf(item);if(from<0||to<0||from===to)return;const [moved]=session.pages.splice(from,1);session.pages.splice(to,0,moved);renderAssembly()};card.append(canvas,name,number,actions);grid.append(card);(async()=>{try{const p=await session.sources[item.source].preview.getPage(item.index+1),base=p.getViewport({scale:1}),v=p.getViewport({scale:Math.min(140/base.width,180/base.height)});canvas.width=Math.ceil(v.width);canvas.height=Math.ceil(v.height);await p.render({canvas,viewport:v}).promise}catch{canvas.replaceWith(document.createTextNode('预览不可用'))}})()}}
$('assemble-cancel').onclick=()=>{if(!assembly?.loading)$('assemble-dialog').close()};$('assemble-dialog').addEventListener('cancel',e=>{if(assembly?.loading)e.preventDefault()});$('assemble-dialog').addEventListener('close',()=>{const old=assembly;assembly=null;$('assemble-grid').replaceChildren();if(old)for(const src of old.sources)if(src.owned)src.preview.loadingTask.destroy().catch(()=>{})});
$('assemble-apply').onclick=async()=>{const session=assembly;if(!session||session.loading||session.tab!==activeTab||!session.pages.length)return;session.loading=true;operationBusy=true;updateEditControls();$('assemble-apply').disabled=$('assemble-add').disabled=$('assemble-cancel').disabled=true;try{const prior=new Uint8Array(session.tab.bytes||await session.tab.doc.getData());if(!session.tab.savedBytes)session.tab.savedBytes=prior;const output=await PDFLib.PDFDocument.create();for(const [i,item] of session.pages.entries()){ $('assemble-status').textContent='正在整理 '+(i+1)+' / '+session.pages.length;const [copy]=await output.copyPages(session.sources[item.source].pdf,[item.index]);output.addPage(copy)}const bytes=await output.save();if(bytes.length>256*1024*1024)throw Error('结果超过 256 MiB');await installEditedBytes(session.tab,bytes,Math.min(session.page,session.pages.length));session.tab.history.push({bytes:prior,page:session.page});session.tab.dirty=true;updateTabs();session.loading=false;$('assemble-dialog').close();status('页面已整理，请保存或另存副本并检查结果')}catch(err){$('assemble-status').textContent='整理失败：'+err.message}finally{session.loading=false;operationBusy=false;updateEditControls();$('assemble-apply').disabled=$('assemble-add').disabled=$('assemble-cancel').disabled=false}};
